const WithPhoto = () => <ReviewCard
    author="Michael T."
    date="April 8, 2026"
    rating={5}
    reviewText="My 3-year-old absolutely loves this toy car! The colors are vibrant, and it's the perfect size for little hands. The quality is outstanding—it's survived countless crashes and is still in perfect condition. Highly recommend!"
    photoUrl={photo1} />;

const TextOnly = () => <ReviewCard
    author="Jessica L."
    date="April 5, 2026"
    rating={4}
    reviewText="Really nice toy car with smooth wheels that roll easily. My daughter enjoys playing with it every day. The only minor issue is that the paint chipped slightly after a few weeks, but overall a solid purchase." />;

const SustainableToyReview = () => <ReviewCard
    author="David K."
    date="April 1, 2026"
    rating={5}
    reviewText="Bought this for my nephew's birthday and it was a hit! The quality is excellent and it feels very sturdy. Love that it's made from sustainable materials too."
    photoUrl={photo2} />;

const ToddlerReview = () => <ReviewCard
    author="Emily R."
    date="March 28, 2026"
    rating={5}
    reviewText="Perfect for toddlers! The size is just right, not too big or small. The wheels move smoothly and it's easy to clean. My twins play with it together and it's holding up great."
    photoUrl={photo3} />;

